The cumulative histogram shows delivery times recorded in whole minutes. Find the exact five-number summary using the median-of-halves convention.
[tikz]
\begin{tikzpicture}[x=10mm,y=2mm,every node/.style={text=black,font=\fontsize{10}{12}\selectfont}]
\draw[gray!40] (0,0) grid[xstep=10mm,ystep=8mm] (7,16);
\draw[black,->] (0,0)--(7.4,0);
\draw[black,->] (0,0)--(0,18);
\foreach \v in {0,4,8,12,16}{\path (0,\v) node[left,font=\fontsize{8.5}{10}\selectfont] {$\v$};}
\foreach \i/\s/\c in {0/10/0,1/11/2,2/12/4,3/13/8,4/14/12,5/15/16,6/16/16}{\draw[black] (\i,0) rectangle ({\i+1},\c);\path ({\i+0.5},0) node[below,font=\fontsize{8.5}{10}\selectfont] {$\s$};\path ({\i+0.5},\c) node[above] {$\c$};}
\path (3.5,-4) node {Delivery time (min)};
\path (-1.1,8) node[rotate=90] {Cumulative frequency};
\end{tikzpicture}
[/tikz]

